/// <summary>
/// The data contract for a <c>METSalesOrderCancelledBusinessEvent</c>.
/// </summary>
[DataContract]
public final class METSalesOrderCancelledBusinessEventContract extends BusinessEventsContract
{
    private LegalEntityDataAreaId legalEntity;

}

Method.Source:
    /// <summary>
    /// Creates an instance of <C>METSalesOrderCancelledBusinessEventContract</C>
    /// </summary>
    /// <param name = "_salesLine">sales line record</param>
    /// <returns>new instance of <C>METSalesOrderCancelledBusinessEventContract</C></returns>
    public static METSalesOrderCancelledBusinessEventContract newFromSalesCancellation(SalesLine _salesLine)
    {
        METSalesOrderCancelledBusinessEventContract contract = new METSalesOrderCancelledBusinessEventContract();
                     
        contract.legalEntity = _salesLine.DataAreaId;

        return contract;
    }

    /// <summary>
    /// Gets/sets the company ID
    /// </summary>
    /// <param name = "_legalEntity">company ID</param>
    /// <returns>returns the company ID</returns>
    [DataMember('LegalEntity'), BusinessEventsDataMember("@SYS315616")]
    public LegalEntityDataAreaId parmLegalEntity(LegalEntityDataAreaId _legalEntity = legalEntity)
    {
        legalEntity = _legalEntity;

        return legalEntity;
    }
